  SequencerAnimationEngine.endAnimations(this.id);
  if (this._maskContainer) this._maskContainer.destroy({ children: true });
  this._maskContainer = null;
  if (this._maskSprite) {
    try {
      this._maskSprite.texture.destroy(true);
      this._maskSprite.destroy();
    } catch (err) {
